struct Camera {
    view_proj: mat4x4<f32>,
    world_position: vec3<f32>,
    viewport_aspect: f32,
    view: mat4x4<f32>,
};

@group(0) @binding(0) var<uniform> camera: Camera;
@group(1) @binding(0) var sprite_texture: texture_2d<f32>;
@group(1) @binding(1) var sprite_sampler: sampler;

struct VertexInput {
    @location(0) position: vec3<f32>,
    @location(3) uv: vec2<f32>,
    @location(4) model_0: vec4<f32>,
    @location(5) model_1: vec4<f32>,
    @location(6) model_2: vec4<f32>,
    @location(7) model_3: vec4<f32>,
    @location(8) tint: vec4<f32>,
    @location(9) uv_transform: vec4<f32>,
};

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
    @location(1) tint: vec4<f32>,
};

@vertex
fn vs_main(input: VertexInput) -> VertexOutput {
    let model = mat4x4<f32>(input.model_0, input.model_1, input.model_2, input.model_3);
    var output: VertexOutput;
    output.position = camera.view_proj * model * vec4<f32>(input.position, 1.0);
    output.uv = input.uv * input.uv_transform.xy + input.uv_transform.zw;
    output.tint = input.tint;
    return output;
}

fn sampled(input: VertexOutput) -> vec4<f32> {
    return textureSample(sprite_texture, sprite_sampler, input.uv) * input.tint;
}

@fragment
fn fs_alpha(input: VertexOutput) -> @location(0) vec4<f32> {
    return sampled(input);
}

@fragment
fn fs_premultiplied(input: VertexOutput) -> @location(0) vec4<f32> {
    let color = sampled(input);
    return vec4<f32>(color.rgb * color.a, color.a);
}

@fragment
fn fs_additive(input: VertexOutput) -> @location(0) vec4<f32> {
    return sampled(input);
}
